flip-bifunctor-NI : F ≃ G → flip-bifunctor F ≃ flip-bifunctor G
-- Steps 1-4: the flipped functors are bifunctors, by flip-F₁-def, flip-F₁-id and flip-F₁-homo applied to F and G.
-- Steps 5-10: beta at (X,Y) is alpha at (Y,X); niHelper derives inverse naturality (step 9) and assembles the natural isomorphism (step 10).
flip-bifunctor-NI α = niHelper record
  { -- Step 5: beta at (X,Y) is alpha at (Y,X), a morphism F^op×(X,Y) → G^op×(X,Y).
    η = λ XY → {!!}
  ; -- Step 6: the inverse component is alpha⁻¹ at (Y,X), a two-sided inverse of beta.
    η⁻¹ = λ XY → {!!}
  ; -- Steps 7-8: naturality of beta is the naturality square of alpha at (g, f).
    commute = λ {XY} {X'Y'} fg → {!!}
  ; -- Step 6: each beta component is an isomorphism.
    iso = λ XY → record
      { -- Step 6: left inverse law, using alpha⁻¹ at (Y,X).
        isoˡ = {!!}
      ; -- Step 6: right inverse law, using alpha⁻¹ at (Y,X).
        isoʳ = {!!}
      }
  }

